// A finite wrapper around the native pipeline. The terrain, caves, ores,
// vegetation and structure pieces are still generated by the real engine.
use super::*;
use crate::veio_map::{Bounds, Dimension};
use super::super::structure::start::StructureStart;
type Cached = (std::path::PathBuf, std::sync::Weak<dyn SeededPipeline>, std::sync::Weak<dyn SeededPipeline>);
static WRAPPERS: Mutex<Vec<Cached>> = Mutex::new(Vec::new());

struct FinitePipeline {
    inner: Arc<dyn SeededPipeline>,
    bounds: Bounds,
    specs: Vec<Value>,
    reserved: Mutex<Option<Vec<Arc<StructureStart>>>>,
    resources: super::veio_resources::Patches,
}

/// Installed only after a new world's certificate is saved. Unmarked worlds
/// keep their exact original pipeline, including unexplored chunks.
pub fn worker(mut worker: GeneratorWorker) -> GeneratorWorker {
    let Some(session) = crate::veio_map::session() else {
        WRAPPERS.lock().unwrap_or_else(|p|p.into_inner()).clear();
        return worker;
    };
    let mut cache = WRAPPERS.lock().unwrap_or_else(|p|p.into_inner());
    cache.retain(|(root, base, wrapper)| root == &session.root && base.strong_count() > 0 && wrapper.strong_count()>0);
    if let Some(wrapper) = cache.iter().find_map(|(_,base,wrapper)|base.upgrade().filter(|p|Arc::ptr_eq(p,&worker.pipeline)).and_then(|_|wrapper.upgrade())) {
        worker.pipeline = wrapper;
        return worker;
    }
    let name = worker.noise_biomes(&[[0,16,0]]).into_iter().next().flatten().expect("dimension biome");
    let dimension = [Dimension::Overworld, Dimension::Nether, Dimension::End].into_iter()
        .find(|d|session.plan["dimensions"][d.id()]["biomes"].get(&name).is_some()).expect("certified dimension");
    let specs = session.plan["dimensions"][dimension.id()]["structures"].as_array().expect("validated certificate").clone();
    let wrapper: Arc<dyn SeededPipeline> = Arc::new(FinitePipeline { inner: worker.pipeline.clone(),
        bounds: dimension.bounds(), specs, reserved: Mutex::new(None),resources:super::veio_resources::decode(worker.pipeline.data(),&session.plan["dimensions"][dimension.id()]["resources"]).expect("validated resource habitats") });
    cache.push((session.root.clone(),Arc::downgrade(&worker.pipeline),Arc::downgrade(&wrapper)));
    worker.pipeline=wrapper;
    worker
}

impl FinitePipeline {
    fn habitat_intersects(&self,s:&StructureStart)->bool {
        self.resources.keys().any(|&(x,z)| x>=(s.bounding_box.min[0]>>4)&&x<=(s.bounding_box.max[0]>>4)&&z>=(s.bounding_box.min[2]>>4)&&z<=(s.bounding_box.max[2]>>4))
    }
    fn starts(&self, worker: &mut WorkerState) -> Result<Vec<Arc<StructureStart>>, GeneratorError> {
        let mut cached = self.reserved.lock().unwrap_or_else(|p| p.into_inner());
        if cached.is_none() {
            let mut made = Vec::new();
            for spec in &self.specs {
                let name = spec["name"].as_str().expect("structure name");
                let pos = ChunkPos::new(spec["chunk"][0].as_i64().unwrap() as i32, spec["chunk"][1].as_i64().unwrap() as i32);
                let start = self.inner.structure_start(worker, name, pos).ok_or_else(|| resource(format!("finite world: missing reserved {name}")))?;
                let expected = |field: &str| std::array::from_fn(|a| spec[field][a].as_i64().unwrap() as i32);
                if start.bounding_box.min != expected("min") || start.bounding_box.max != expected("max") {
                    return Err(resource(format!("finite world: incompatible reserved structure {name}")));
                }
                made.push(start);
            }
            *cached = Some(made);
        }
        Ok(cached.as_ref().unwrap().clone())
    }
    fn blank(&self, pos: ChunkPos) -> Result<ProtoChunk, GeneratorError> {
        let data = self.inner.data().clone();
        let (min, height) = self.inner.level();
        let mut terrain = TerrainChunk::new(pos, min, height, data.registry, data.states.clone()).map_err(stage("finite empty terrain"))?;
        terrain.set_generation_stage(PreLightChunkStage::Terrain);
        let biomes = BiomeChunk::new(pos, min, height, BiomeId(0)).map_err(stage("finite empty biomes"))?;
        Ok(ProtoChunk { terrain, biomes, data, decorated: false, block_entities: Vec::new(),
            structure_starts: Vec::new(), own_starts: Starts::default(), entities: Vec::new() })
    }
    fn trim(&self, chunk: &mut ProtoChunk) -> Result<(), GeneratorError> {
        let pos = chunk.position();
        if self.bounds.contains((pos.x * 16) as f64, (pos.z * 16) as f64, 16.0)
            && self.bounds.contains((pos.x * 16 + 15) as f64, (pos.z * 16 + 15) as f64, 16.0) { return Ok(()); }
        let (min, height) = self.inner.level();
        let bedrock = chunk.data.registry.default_state("minecraft:bedrock").ok_or_else(|| resource("missing bedrock"))?;
        let air = chunk.data.registry.default_state("minecraft:air").ok_or_else(|| resource("missing air"))?;
        for z in pos.z * 16..pos.z * 16 + 16 {
            for x in pos.x * 16..pos.x * 16 + 16 {
                let state = if self.bounds.shell(x, z) { bedrock } else if !self.bounds.column(x,z) { air } else { continue; };
                for y in min..min + height { chunk.terrain.set_block_raw(x,y,z,state).map_err(stage("finite wall"))?; }
            }
        }
        chunk.block_entities.retain(|(p,_)| self.bounds.contains(p[0] as f64,p[2] as f64,0.0) && !self.bounds.shell(p[0],p[2]));
        chunk.entities.retain(|c| {
            let Some(crate::nbt::Tag::List(p))=c.get(&"Pos".into()) else{return false;};
            let number=|i:usize|match p.get(i){Some(crate::nbt::Tag::Double(v))=>f64::from_bits(*v),Some(crate::nbt::Tag::Float(v))=>f64::from(f32::from_bits(*v)),_=>f64::NAN};
            self.bounds.contains(number(0),number(2),1.0)
        });
        let valid=|p:horizon_core::position::BlockPos|self.bounds.contains(p.x as f64,p.z as f64,0.0)&&!self.bounds.shell(p.x,p.z);
        *chunk.terrain.block_ticks_mut()=horizon_core::ticks::ProtoChunkTicks::from_saved(chunk.terrain.block_ticks().pack(0).iter().filter(|t|valid(t.pos)).cloned().collect::<Vec<_>>());
        *chunk.terrain.fluid_ticks_mut()=horizon_core::ticks::ProtoChunkTicks::from_saved(chunk.terrain.fluid_ticks().pack(0).iter().filter(|t|valid(t.pos)).cloned().collect::<Vec<_>>());
        chunk.terrain.prime_heightmaps(&[HeightmapType::WorldSurfaceWg,HeightmapType::OceanFloorWg,HeightmapType::MotionBlocking,HeightmapType::MotionBlockingNoLeaves,HeightmapType::OceanFloor,HeightmapType::WorldSurface]).map_err(stage("finite heightmaps"))?;
        Ok(())
    }
    fn references(&self, worker: &mut WorkerState, pos: ChunkPos, existing: Vec<Arc<StructureStart>>) -> Result<Vec<Arc<StructureStart>>, GeneratorError> {
        let reserved = self.starts(worker)?;
        let bounds = super::super::structure::BoundingBox::new([pos.x * 16, self.inner.level().0, pos.z * 16], [pos.x * 16+15, self.inner.level().0+self.inner.level().1-1, pos.z*16+15]);
        let mut result: Vec<_> = existing.into_iter().filter(|s| self.bounds.contains_box(s.bounding_box.min,s.bounding_box.max,2.0)
            && !self.habitat_intersects(s) && !reserved.iter().any(|r| r.bounding_box.intersects(&s.bounding_box))).collect();
        result.extend(reserved.into_iter().filter(|s| s.bounding_box.intersects(&bounds)));
        Ok(result)
    }
}

impl SeededPipeline for FinitePipeline {
    fn generate(&self, worker: &mut WorkerState, pos: ChunkPos) -> Result<ProtoChunk, GeneratorError> {
        if !self.bounds.chunk(pos.x,pos.z,0) { return self.blank(pos); }
        let mut chunk = self.inner.generate(worker,pos)?;
        chunk.structure_starts = self.references(worker,pos,std::mem::take(&mut chunk.structure_starts))?;
        chunk.own_starts = Arc::new(self.structure_starts(worker,pos));
        self.trim(&mut chunk)?;
        Ok(chunk)
    }
    fn decorate(&self, worker: &mut WorkerState, region: &mut [ProtoChunk;9]) -> Result<DecorateStats,GeneratorError> {
        let p = region[4].position();
        if !self.bounds.chunk(p.x,p.z,0) { region[4].decorated = true; return Ok(DecorateStats::default()); }
        // Full chunks are editable player data (proto_beside_final restores
        // their blocks before a new neighbour decorates). Preserve their exact
        // current habitat cells; otherwise a later neighbour could replenish a
        // mined vein, erase a building, or duplicate bees/archaeology loot.
        let frozen:Vec<_>=region.iter().map(|c| {
            if !c.is_decorated(){return None;}
            let p=c.position();let blocks=self.resources.get(&(p.x,p.z))?;
            let cells:Vec<_>=blocks.iter().map(|&(at,_)|(at,c.block(at[0],at[1],at[2]))).collect();
            let positions:BTreeSet<_>=blocks.iter().map(|&(at,_)|at).collect();
            let entities:Vec<_>=c.block_entities.iter().filter(|(at,_)|positions.contains(at)).cloned().collect();
            Some((cells,positions,entities))
        }).collect();
        let was_decorated:Vec<_>=region.iter().map(ProtoChunk::is_decorated).collect();
        let stats = self.inner.decorate(worker,region)?;
        for (i,c) in region.iter_mut().enumerate() {
            if let Some((cells,positions,entities))=&frozen[i] {
                for &(at,id) in cells {c.terrain.set_block_raw(at[0],at[1],at[2],id).map_err(stage("preserve resource habitat"))?;}
                c.block_entities.retain(|(p,_)|!positions.contains(p));c.block_entities.extend(entities.iter().cloned());
            } else if !was_decorated[i] {super::veio_resources::apply(c,&self.resources)?;}
            self.trim(c)?;
        }
        Ok(stats)
    }
    fn data(&self) -> &Arc<GeneratorData> { self.inner.data() }
    fn cache_census(&self) -> CacheCensus { self.inner.cache_census() }
    fn release_caches(&self) { self.inner.release_caches(); }
    fn end_island_origins(&self, pos:ChunkPos)->Vec<[i32;3]> { if self.bounds.chunk(pos.x,pos.z,0) { self.inner.end_island_origins(pos) } else { Vec::new() } }
    fn sea_level(&self)->i32 { self.inner.sea_level() }
    fn level(&self)->(i32,i32) { self.inner.level() }
    fn surface_sample(&self, worker:&mut WorkerState,x:i32,z:i32,spans:Option<&mut Vec<(i32,i32,BlockStateId)>>)->Option<SurfaceSample> {
        if !self.bounds.column(x,z) { return None; }
        if self.bounds.shell(x,z) {
            let (min,height)=self.inner.level(); let state=self.inner.data().registry.default_state("minecraft:bedrock")?;
            if let Some(spans)=spans { spans.push((min,min+height,state)); }
            return Some(SurfaceSample{height:min+height,state,water:None,biome:BiomeId(0)});
        }
        self.inner.surface_sample(worker,x,z,spans)
    }
    fn lod_grid(&self,worker:&mut WorkerState,x:i32,z:i32,width:i32,side:usize,approximate:bool)->Result<Vec<LodColumn>,GeneratorError> {
        if self.bounds.contains(x as f64,z as f64,32.0) && self.bounds.contains((i64::from(x)+i64::from(width)*side as i64) as f64,(i64::from(z)+i64::from(width)*side as i64) as f64,32.0) { return self.inner.lod_grid(worker,x,z,width,side,approximate); }
        let mut out=Vec::with_capacity(side*side);
        for dz in 0..side { for dx in 0..side { let mut spans=Vec::new(); let surface=self.surface_sample(worker,x+dx as i32*width,z+dz as i32*width,Some(&mut spans)); out.push((surface,spans)); } }
        Ok(out)
    }
    fn structure_starts(&self,worker:&mut WorkerState,pos:ChunkPos)->Vec<Arc<StructureStart>> {
        if !self.bounds.chunk(pos.x,pos.z,0) { return Vec::new(); }
        let mut out=self.inner.structure_starts(worker,pos);
        let reserved=self.starts(worker).expect("reserved structures validated before entry");
        out.retain(|s| self.bounds.contains_box(s.bounding_box.min,s.bounding_box.max,2.0) && !self.habitat_intersects(s) && !reserved.iter().any(|r| r.bounding_box.intersects(&s.bounding_box)));
        out.extend(reserved.into_iter().filter(|s|s.chunk==pos)); out
    }
    fn structure_start(&self,worker:&mut WorkerState,name:&str,pos:ChunkPos)->Option<Arc<StructureStart>> { let s=self.inner.structure_start(worker,name,pos)?; self.bounds.contains_box(s.bounding_box.min,s.bounding_box.max,2.0).then_some(s) }
    fn unsupported_features(&self)->Vec<(String,String)> { self.inner.unsupported_features() }
    fn use_saved_start(&self,worker:&mut WorkerState,pos:ChunkPos,name:&str,pieces:&[Value])->Result<(),String> { self.inner.use_saved_start(worker,pos,name,pieces) }
    fn forget_structure_starts(&self) { self.inner.forget_structure_starts(); }
    fn ring_positions(&self,worker:&mut WorkerState,name:&str)->Option<Vec<ChunkPos>> { self.inner.ring_positions(worker,name).map(|v|v.into_iter().filter(|p|self.bounds.chunk(p.x,p.z,0)).collect()) }
    fn spawn_position(&self)->Result<[i32;2],GeneratorError> { let [x,z]=self.inner.spawn_position()?; let [x,z]=self.bounds.clamp(x as f64,z as f64,256.0).ok_or_else(||resource("invalid spawn"))?; Ok([x as i32,z as i32]) }
    fn region_random(&self,pos:ChunkPos)->Box<dyn super::super::structure::legacy::PieceRandom> { self.inner.region_random(pos) }
    fn locate(&self,worker:&mut WorkerState,names:&[String],from:[i32;3],radius:i32,skip:&dyn Fn(&str,ChunkPos)->bool)->Option<(String,[i32;3])> {
        let forced=self.starts(worker).ok()?.into_iter().filter(|s|names.contains(&s.name)&&!skip(&s.name,s.chunk)).map(|s|(s.name.clone(),[s.chunk.x*16,0,s.chunk.z*16]));
        let natural=self.inner.locate(worker,names,from,radius,&|name,pos|skip(name,pos)||!self.bounds.chunk(pos.x,pos.z,0));
        forced.chain(natural).min_by_key(|(_,p)| { let x=i64::from(p[0])-i64::from(from[0]); let z=i64::from(p[2])-i64::from(from[2]); x*x+z*z })
    }
    fn set_old_world(&self,world:Arc<dyn super::super::blending::OldWorld>) { self.inner.set_old_world(world); }
    fn debug_density_line(&self,feet:[i32;3])->Option<String> { self.inner.debug_density_line(feet) }
    fn find_closest_biome(&self,worker:&mut WorkerState,query:&BiomeSearch<'_>)->Option<(String,[i32;3])> {
        let allowed=|b:&str|(query.allowed)(b);
        let bounded=BiomeSearch{allowed:&allowed,radius:query.radius.min(15_000),..*query};
        self.inner.find_closest_biome(worker,&bounded).filter(|(_,p)|self.bounds.contains(p[0] as f64,p[2] as f64,2.0))
    }
    fn noise_biomes(&self,worker:&mut WorkerState,quarts:&[[i32;3]])->Vec<Option<String>> { self.inner.noise_biomes(worker,quarts) }
    fn jigsaw_pieces(&self,worker:&mut WorkerState,query:&JigsawQuery<'_>)->Option<JigsawPieces> { if !self.bounds.contains(query.position[0] as f64,query.position[2] as f64,128.0) {return None;} self.inner.jigsaw_pieces(worker,query) }
}
